/* ===== OpenLearnHub Design System ===== */

/* --- OKLCH Color Tokens --- */
:root {
  --color-primary: oklch(15% 0.05 265);
  --color-primary-light: oklch(22% 0.06 265);
  --color-accent: oklch(80% 0.16 85);
  --color-accent-hover: oklch(75% 0.18 85);
  --color-link: oklch(40% 0.20 265);
  --color-link-hover: oklch(50% 0.22 265);

  --color-bg: oklch(99% 0.005 265);
  --color-bg-card: oklch(100% 0 0);
  --color-bg-elevated: oklch(97% 0.005 265);

  --color-text: oklch(20% 0.02 265);
  --color-text-secondary: oklch(45% 0.02 265);
  --color-text-muted: oklch(60% 0.015 265);
  --color-text-inverse: oklch(98% 0.005 265);

  --color-border: oklch(92% 0.01 265);
  --color-border-light: oklch(96% 0.005 265);

  --color-tag-ai: oklch(55% 0.18 265);
  --color-tag-scraping: oklch(60% 0.15 145);
  --color-tag-db: oklch(50% 0.17 300);
  --color-tag-search: oklch(60% 0.18 30);
  --color-tag-data: oklch(55% 0.16 200);
  --color-tag-python: oklch(60% 0.18 85);
  --color-tag-node: oklch(55% 0.18 145);
  --color-tag-sheets: oklch(60% 0.16 145);
  --color-tag-automation: oklch(50% 0.15 30);

  --radius-sm: 4px;
  --radius-md: 8px;
  --radius-lg: 12px;
  --radius-xl: 16px;

  --shadow-sm: 0 1px 3px oklch(0% 0 0 / 0.08);
  --shadow-md: 0 2px 8px oklch(0% 0 0 / 0.1);
  --shadow-lg: 0 4px 16px oklch(0% 0 0 / 0.12);

  --font-sans: 'Inter', system-ui, -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
  --font-mono: 'Fira Code', 'Cascadia Code', ui-monospace, monospace;

  --space-xs: 4px;
  --space-sm: 8px;
  --space-md: 16px;
  --space-lg: 24px;
  --space-xl: 32px;
  --space-2xl: 48px;
  --space-3xl: 64px;

  --max-width: 1200px;
  --header-height: 64px;
}

/* --- Reset & Base --- */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

html { font-size: 16px; -webkit-font-smoothing: antialiased; -moz-osx-font-smoothing: grayscale; }

body {
  font-family: var(--font-sans);
  color: var(--color-text);
  background: var(--color-bg);
  line-height: 1.6;
  min-height: 100vh;
}

a { color: var(--color-link); text-decoration: none; transition: color 0.2s; }
a:hover { color: var(--color-link-hover); }

img { max-width: 100%; display: block; }

ul, ol { list-style: none; }

button { cursor: pointer; font-family: inherit; border: none; background: none; }

/* --- Container --- */
.container {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 var(--space-lg);
}

/* --- Header --- */
.site-header {
  background: var(--color-primary);
  height: var(--header-height);
  position: sticky;
  top: 0;
  z-index: 100;
}

.header-inner {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 var(--space-lg);
  display: flex;
  align-items: center;
  height: 100%;
  gap: var(--space-lg);
}

.header-logo {
  color: var(--color-text-inverse);
  font-size: 1.25rem;
  font-weight: 700;
  white-space: nowrap;
  letter-spacing: -0.02em;
}

.header-logo span {
  color: var(--color-accent);
}

.header-search {
  flex: 1;
  max-width: 420px;
  position: relative;
}

.header-search input {
  width: 100%;
  padding: 8px 16px 8px 36px;
  border-radius: 20px;
  border: none;
  background: oklch(25% 0.04 265);
  color: var(--color-text-inverse);
  font-size: 0.875rem;
  outline: none;
  transition: background 0.2s;
}

.header-search input::placeholder { color: oklch(65% 0.02 265); }
.header-search input:focus { background: oklch(30% 0.05 265); }

.header-search .search-icon {
  position: absolute;
  left: 12px;
  top: 50%;
  transform: translateY(-50%);
  color: oklch(65% 0.02 265);
  font-size: 0.875rem;
}

.header-nav {
  display: flex;
  align-items: center;
  gap: var(--space-xl);
}

.header-nav a {
  color: oklch(85% 0.01 265);
  font-size: 0.9375rem;
  font-weight: 500;
  transition: color 0.2s;
  white-space: nowrap;
}

.header-nav a:hover { color: var(--color-accent); }

.hamburger {
  display: none;
  flex-direction: column;
  gap: 5px;
  padding: 4px;
  cursor: pointer;
}

.hamburger span {
  display: block;
  width: 22px;
  height: 2px;
  background: var(--color-text-inverse);
  border-radius: 2px;
  transition: transform 0.3s, opacity 0.3s;
}

.hamburger.active span:nth-child(1) { transform: translateY(7px) rotate(45deg); }
.hamburger.active span:nth-child(2) { opacity: 0; }
.hamburger.active span:nth-child(3) { transform: translateY(-7px) rotate(-45deg); }

.mobile-nav {
  display: none;
  background: var(--color-primary);
  border-top: 1px solid oklch(25% 0.04 265);
  padding: var(--space-md) var(--space-lg);
}

.mobile-nav.active { display: block; }

.mobile-nav a {
  display: block;
  color: oklch(85% 0.01 265);
  padding: var(--space-sm) 0;
  font-size: 1rem;
  font-weight: 500;
}

.mobile-nav a:hover { color: var(--color-accent); }

/* --- Hero Banner --- */
.hero-banner {
  background: oklch(25% 0.06 265);
  text-align: center;
  padding: var(--space-md) var(--space-lg);
}

.hero-banner p {
  color: oklch(90% 0.01 265);
  font-size: 1rem;
  font-weight: 500;
}

.hero-banner a {
  color: var(--color-accent);
  font-weight: 600;
}

.hero-banner a:hover { text-decoration: underline; }

/* --- Featured Article --- */
.featured-article {
  padding: var(--space-2xl) 0;
}

.featured-card {
  position: relative;
  border-radius: var(--radius-lg);
  overflow: hidden;
  background: var(--color-primary);
  min-height: 380px;
  display: flex;
  align-items: flex-end;
  transition: transform 0.2s;
}

.featured-card:hover { transform: translateY(-2px); }

.featured-card .featured-thumb {
  position: absolute;
  inset: 0;
  background: linear-gradient(135deg, oklch(30% 0.08 265), oklch(20% 0.06 200));
  z-index: 0;
}

.featured-card .featured-thumb::after {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(to top, oklch(10% 0.05 265 / 0.9) 0%, oklch(10% 0.05 265 / 0.3) 50%, transparent 100%);
}

.featured-content {
  position: relative;
  z-index: 1;
  padding: var(--space-xl);
  width: 100%;
}

.featured-tag {
  display: inline-block;
  background: var(--color-tag-ai);
  color: white;
  padding: 3px 10px;
  border-radius: var(--radius-sm);
  font-size: 0.75rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  margin-bottom: var(--space-sm);
}

.featured-title {
  color: var(--color-text-inverse);
  font-size: 1.75rem;
  font-weight: 700;
  line-height: 1.3;
  margin-bottom: var(--space-md);
  max-width: 600px;
}

.featured-meta {
  display: flex;
  align-items: center;
  gap: var(--space-sm);
  color: oklch(80% 0.01 265);
  font-size: 0.875rem;
}

.author-avatar {
  width: 28px;
  height: 28px;
  border-radius: 50%;
  background: oklch(60% 0.1 265);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 0.7rem;
  font-weight: 700;
  color: white;
  flex-shrink: 0;
}

/* --- Section Headers --- */
.section-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: var(--space-lg);
  padding-bottom: var(--space-sm);
  border-bottom: 2px solid var(--color-border);
}

.section-title {
  font-size: 1.375rem;
  font-weight: 700;
  color: var(--color-text);
}

.section-link {
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--color-link);
}

/* --- Article Grid --- */
.articles-section {
  padding: 0 0 var(--space-3xl);
}

.article-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--space-lg);
}

.article-card {
  background: var(--color-bg-card);
  border-radius: var(--radius-lg);
  overflow: hidden;
  box-shadow: var(--shadow-sm);
  border: 1px solid var(--color-border-light);
  transition: transform 0.2s, box-shadow 0.2s;
}

.article-card:hover {
  transform: translateY(-2px);
  box-shadow: var(--shadow-md);
}

.card-thumb {
  height: 160px;
  background: linear-gradient(135deg, oklch(70% 0.06 265), oklch(60% 0.04 200));
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
}

.card-thumb .card-icon {
  font-size: 2.5rem;
  opacity: 0.3;
}

.card-tag {
  position: absolute;
  top: var(--space-sm);
  left: var(--space-sm);
  padding: 2px 8px;
  border-radius: var(--radius-sm);
  font-size: 0.6875rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  color: white;
}

.tag-ai { background: var(--color-tag-ai); }
.tag-scraping { background: var(--color-tag-scraping); }
.tag-db { background: var(--color-tag-db); }
.tag-search { background: var(--color-tag-search); }
.tag-data { background: var(--color-tag-data); }
.tag-python { background: var(--color-tag-python); }
.tag-node { background: var(--color-tag-node); }
.tag-sheets { background: var(--color-tag-sheets); }
.tag-automation { background: var(--color-tag-automation); }

.card-body {
  padding: var(--space-md);
}

.card-title {
  font-size: 1rem;
  font-weight: 600;
  line-height: 1.4;
  margin-bottom: var(--space-sm);
  color: var(--color-text);
  display: -webkit-box;
  -webkit-line-clamp: 3;
  -webkit-box-orient: vertical;
  overflow: hidden;
}

.card-title a { color: inherit; }
.card-title a:hover { color: var(--color-link); }

.card-meta {
  display: flex;
  align-items: center;
  gap: var(--space-sm);
  font-size: 0.8125rem;
  color: var(--color-text-muted);
}

.card-meta .author-name { font-weight: 500; color: var(--color-text-secondary); }
.card-meta .separator { color: var(--color-border); }

/* --- Load More --- */
.load-more-wrapper {
  text-align: center;
  margin-top: var(--space-2xl);
}

.btn-load-more {
  background: var(--color-primary);
  color: var(--color-text-inverse);
  padding: 12px 32px;
  border-radius: var(--radius-md);
  font-size: 0.9375rem;
  font-weight: 600;
  transition: background 0.2s, transform 0.1s;
}

.btn-load-more:hover { background: var(--color-primary-light); }
.btn-load-more:active { transform: scale(0.98); }

/* --- Learn Page --- */
.page-intro {
  padding: var(--space-2xl) 0 var(--space-xl);
  text-align: center;
}

.page-intro h1 {
  font-size: 2rem;
  font-weight: 700;
  margin-bottom: var(--space-sm);
}

.page-intro p {
  color: var(--color-text-secondary);
  font-size: 1.0625rem;
  max-width: 520px;
  margin: 0 auto;
}

.curriculum-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
  gap: var(--space-md);
  padding-bottom: var(--space-2xl);
}

.cert-card {
  background: var(--color-bg-card);
  border: 1px solid var(--color-border-light);
  border-radius: var(--radius-lg);
  padding: var(--space-lg);
  display: flex;
  align-items: flex-start;
  gap: var(--space-md);
  transition: border-color 0.2s, box-shadow 0.2s;
  cursor: pointer;
}

.cert-card:hover {
  border-color: var(--color-accent);
  box-shadow: var(--shadow-md);
}

.cert-icon {
  width: 44px;
  height: 44px;
  border-radius: var(--radius-md);
  background: oklch(95% 0.02 85);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.25rem;
  flex-shrink: 0;
}

.cert-info h3 {
  font-size: 1rem;
  font-weight: 600;
  margin-bottom: 2px;
}

.cert-info p {
  font-size: 0.8125rem;
  color: var(--color-text-muted);
}

/* Daily Challenge */
.daily-challenge {
  background: oklch(97% 0.02 85);
  border-radius: var(--radius-lg);
  padding: var(--space-xl);
  text-align: center;
  margin-bottom: var(--space-2xl);
}

.daily-challenge h2 {
  font-size: 1.375rem;
  margin-bottom: var(--space-sm);
}

.daily-challenge p {
  color: var(--color-text-secondary);
  margin-bottom: var(--space-md);
}

.daily-challenge-links {
  display: flex;
  justify-content: center;
  gap: var(--space-lg);
  flex-wrap: wrap;
}

.daily-challenge-links a {
  font-weight: 600;
  font-size: 0.9375rem;
}

/* Language & Interview */
.sub-section {
  padding-bottom: var(--space-2xl);
}

.sub-section h2 {
  font-size: 1.375rem;
  font-weight: 700;
  margin-bottom: var(--space-md);
  padding-bottom: var(--space-sm);
  border-bottom: 2px solid var(--color-border);
}

.link-list {
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-sm);
}

.link-list a {
  background: var(--color-bg-card);
  border: 1px solid var(--color-border-light);
  padding: 8px 16px;
  border-radius: var(--radius-md);
  font-size: 0.9375rem;
  font-weight: 500;
  transition: border-color 0.2s, background 0.2s;
}

.link-list a:hover {
  border-color: var(--color-accent);
  background: oklch(98% 0.01 85);
}

/* --- Donate Page --- */
.donate-hero {
  background: var(--color-primary);
  padding: var(--space-3xl) 0;
  text-align: center;
}

.donate-hero h1 {
  color: var(--color-text-inverse);
  font-size: 2.25rem;
  font-weight: 700;
  margin-bottom: var(--space-md);
}

.donate-hero p {
  color: oklch(80% 0.01 265);
  font-size: 1.0625rem;
  max-width: 620px;
  margin: 0 auto;
  line-height: 1.7;
}

/* Donation Form */
.donate-form-section {
  padding: var(--space-2xl) 0;
}

.donate-form-card {
  max-width: 560px;
  margin: 0 auto;
  background: var(--color-bg-card);
  border-radius: var(--radius-xl);
  padding: var(--space-2xl);
  box-shadow: var(--shadow-lg);
}

.amount-tabs {
  display: flex;
  gap: var(--space-sm);
  margin-bottom: var(--space-lg);
}

.amount-tab {
  flex: 1;
  padding: 14px 8px;
  border-radius: var(--radius-md);
  font-size: 1.125rem;
  font-weight: 700;
  text-align: center;
  border: 2px solid var(--color-border);
  background: var(--color-bg-card);
  color: var(--color-text);
  transition: all 0.2s;
}

.amount-tab:hover { border-color: var(--color-accent); }

.amount-tab.active {
  background: var(--color-accent);
  border-color: var(--color-accent);
  color: var(--color-primary);
}

.donate-description {
  text-align: center;
  margin-bottom: var(--space-lg);
  font-size: 1rem;
  color: var(--color-text-secondary);
  line-height: 1.6;
}

.btn-donate {
  display: block;
  width: 100%;
  padding: 16px;
  background: var(--color-accent);
  color: var(--color-primary);
  border-radius: var(--radius-md);
  font-size: 1.125rem;
  font-weight: 700;
  text-align: center;
  transition: background 0.2s, transform 0.1s;
}

.btn-donate:hover { background: var(--color-accent-hover); }
.btn-donate:active { transform: scale(0.98); }

.donate-sublabel {
  text-align: center;
  margin-top: var(--space-sm);
  font-size: 0.8125rem;
  color: var(--color-text-muted);
}

/* Supporter Benefits */
.supporter-section {
  padding: var(--space-2xl) 0;
}

.benefits-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(260px, 1fr));
  gap: var(--space-md);
}

.benefit-item {
  display: flex;
  align-items: flex-start;
  gap: var(--space-md);
  padding: var(--space-md);
  background: var(--color-bg-card);
  border-radius: var(--radius-md);
  border: 1px solid var(--color-border-light);
}

.benefit-icon {
  width: 36px;
  height: 36px;
  border-radius: var(--radius-sm);
  background: oklch(95% 0.02 85);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1rem;
  flex-shrink: 0;
}

.benefit-item p {
  font-size: 0.9375rem;
  line-height: 1.5;
  color: var(--color-text-secondary);
}

/* Initiatives */
.initiatives-section {
  padding: var(--space-2xl) 0;
}

.initiative-list {
  display: grid;
  gap: var(--space-sm);
}

.initiative-item {
  display: flex;
  align-items: flex-start;
  gap: var(--space-md);
  padding: var(--space-md) var(--space-lg);
  background: var(--color-bg-elevated);
  border-radius: var(--radius-md);
}

.initiative-item .initiative-bullet {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--color-accent);
  margin-top: 7px;
  flex-shrink: 0;
}

.initiative-item p {
  font-size: 1rem;
  color: var(--color-text-secondary);
}

/* Achievements */
.achievements-section {
  padding: var(--space-2xl) 0;
}

.achievement-list {
  display: grid;
  gap: var(--space-sm);
}

.achievement-item {
  display: flex;
  align-items: flex-start;
  gap: var(--space-md);
  padding: var(--space-md) var(--space-lg);
  background: var(--color-bg-elevated);
  border-radius: var(--radius-md);
}

.achievement-item .achievement-bullet {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--color-link);
  margin-top: 7px;
  flex-shrink: 0;
}

.achievement-item p {
  font-size: 1rem;
  color: var(--color-text-secondary);
}

/* FAQ Accordion */
.faq-section {
  padding: var(--space-2xl) 0 var(--space-3xl);
}

.faq-list {
  max-width: 720px;
  margin: 0 auto;
}

.faq-item {
  border-bottom: 1px solid var(--color-border);
}

.faq-question {
  display: flex;
  align-items: center;
  justify-content: space-between;
  width: 100%;
  padding: var(--space-md) 0;
  font-size: 1rem;
  font-weight: 600;
  color: var(--color-text);
  text-align: left;
  transition: color 0.2s;
}

.faq-question:hover { color: var(--color-link); }

.faq-chevron {
  font-size: 0.75rem;
  transition: transform 0.3s;
  color: var(--color-text-muted);
  flex-shrink: 0;
  margin-left: var(--space-md);
}

.faq-item.active .faq-chevron { transform: rotate(180deg); }

.faq-answer {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.3s ease, padding 0.3s ease;
}

.faq-answer-inner {
  padding-bottom: var(--space-md);
  font-size: 0.9375rem;
  line-height: 1.7;
  color: var(--color-text-secondary);
}

.faq-item.active .faq-answer {
  max-height: 300px;
}

/* --- Tag Pages --- */
.tag-page-header {
  padding: var(--space-2xl) 0 var(--space-lg);
}

.tag-page-header h1 {
  font-size: 2rem;
  font-weight: 700;
}

.tag-page-header .tag-count {
  color: var(--color-text-muted);
  font-size: 1rem;
  margin-top: var(--space-xs);
}

.popular-tags-section {
  padding-bottom: var(--space-xl);
}

.popular-tags-row {
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-sm);
}

.popular-tag {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 6px 14px;
  background: var(--color-bg-card);
  border: 1px solid var(--color-border-light);
  border-radius: 20px;
  font-size: 0.8125rem;
  font-weight: 500;
  color: var(--color-text-secondary);
  transition: border-color 0.2s, background 0.2s;
  cursor: pointer;
}

.popular-tag:hover {
  border-color: var(--color-accent);
  background: oklch(98% 0.01 85);
}

.popular-tag .tag-count-badge {
  font-size: 0.75rem;
  color: var(--color-text-muted);
  font-weight: 400;
}

/* --- Footer --- */
.site-footer {
  background: var(--color-primary);
  color: oklch(80% 0.01 265);
  padding: var(--space-2xl) 0 var(--space-xl);
}

.footer-inner {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 var(--space-lg);
}

.footer-mission {
  font-size: 0.9375rem;
  line-height: 1.7;
  max-width: 700px;
  margin-bottom: var(--space-xl);
}

.footer-trending h4 {
  color: var(--color-accent);
  font-size: 0.875rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  margin-bottom: var(--space-sm);
}

.footer-trending p {
  font-size: 0.875rem;
  line-height: 1.8;
}

.footer-trending p span {
  color: oklch(85% 0.01 265);
  cursor: pointer;
  transition: color 0.2s;
}

.footer-trending p span:hover { color: var(--color-accent); }

.footer-links {
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-sm) var(--space-md);
  margin-top: var(--space-xl);
  padding-top: var(--space-lg);
  border-top: 1px solid oklch(25% 0.04 265);
}

.footer-links a {
  color: oklch(70% 0.01 265);
  font-size: 0.8125rem;
}

.footer-links a:hover { color: var(--color-accent); }

/* --- Responsive --- */
@media (max-width: 1024px) {
  .article-grid { grid-template-columns: repeat(2, 1fr); }
}

@media (max-width: 768px) {
  .header-search { display: none; }
  .header-nav { display: none; }
  .hamburger { display: flex; }

  .article-grid { grid-template-columns: 1fr; }
  .curriculum-grid { grid-template-columns: 1fr; }

  .featured-title { font-size: 1.375rem; }

  .donate-hero h1 { font-size: 1.75rem; }
  .donate-form-card { padding: var(--space-lg); }

  .amount-tabs { flex-wrap: wrap; }
  .amount-tab { min-width: calc(50% - 4px); }

  .benefits-grid { grid-template-columns: 1fr; }

  .tag-page-header h1 { font-size: 1.5rem; }
  .popular-tags-row { gap: 6px; }
}

@media (max-width: 480px) {
  .container { padding: 0 var(--space-md); }
  .header-inner { padding: 0 var(--space-md); }

  .hero-banner { padding: var(--space-sm) var(--space-md); }
  .hero-banner p { font-size: 0.875rem; }

  .featured-card { min-height: 280px; }
  .featured-content { padding: var(--space-md); }
  .featured-title { font-size: 1.25rem; }
}

/* --- Utility --- */
.visually-hidden {
  position: absolute;
  width: 1px;
  height: 1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
}

/* ===== OpenLearnHub Design System ===== */

/* --- OKLCH Color Tokens --- */
:root {
  --color-primary: oklch(15% 0.05 265);
  --color-primary-light: oklch(22% 0.06 265);
  --color-accent: oklch(80% 0.16 85);
  --color-accent-hover: oklch(75% 0.18 85);
  --color-link: oklch(40% 0.20 265);
  --color-link-hover: oklch(50% 0.22 265);

  --color-bg: oklch(99% 0.005 265);
  --color-bg-card: oklch(100% 0 0);
  --color-bg-elevated: oklch(97% 0.005 265);

  --color-text: oklch(20% 0.02 265);
  --color-text-secondary: oklch(45% 0.02 265);
  --color-text-muted: oklch(60% 0.015 265);
  --color-text-inverse: oklch(98% 0.005 265);

  --color-border: oklch(92% 0.01 265);
  --color-border-light: oklch(96% 0.005 265);

  --color-tag-ai: oklch(55% 0.18 265);
  --color-tag-scraping: oklch(60% 0.15 145);
  --color-tag-db: oklch(50% 0.17 300);
  --color-tag-search: oklch(60% 0.18 30);
  --color-tag-data: oklch(55% 0.16 200);
  --color-tag-python: oklch(60% 0.18 85);
  --color-tag-node: oklch(55% 0.18 145);
  --color-tag-sheets: oklch(60% 0.16 145);
  --color-tag-automation: oklch(50% 0.15 30);

  --radius-sm: 4px;
  --radius-md: 8px;
  --radius-lg: 12px;
  --radius-xl: 16px;

  --shadow-sm: 0 1px 3px oklch(0% 0 0 / 0.08);
  --shadow-md: 0 2px 8px oklch(0% 0 0 / 0.1);
  --shadow-lg: 0 4px 16px oklch(0% 0 0 / 0.12);

  --font-sans: 'Inter', system-ui, -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
  --font-mono: 'Fira Code', 'Cascadia Code', ui-monospace, monospace;

  --space-xs: 4px;
  --space-sm: 8px;
  --space-md: 16px;
  --space-lg: 24px;
  --space-xl: 32px;
  --space-2xl: 48px;
  --space-3xl: 64px;

  --max-width: 1200px;
  --header-height: 64px;
}

/* --- Reset & Base --- */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

html { font-size: 16px; -webkit-font-smoothing: antialiased; -moz-osx-font-smoothing: grayscale; }

body {
  font-family: var(--font-sans);
  color: var(--color-text);
  background: var(--color-bg);
  line-height: 1.6;
  min-height: 100vh;
}

a { color: var(--color-link); text-decoration: none; transition: color 0.2s; }
a:hover { color: var(--color-link-hover); }

img { max-width: 100%; display: block; }

ul, ol { list-style: none; }

button { cursor: pointer; font-family: inherit; border: none; background: none; }

/* --- Container --- */
.container {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 var(--space-lg);
}

/* --- Header --- */
.site-header {
  background: var(--color-primary);
  height: var(--header-height);
  position: sticky;
  top: 0;
  z-index: 100;
}

.header-inner {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 var(--space-lg);
  display: flex;
  align-items: center;
  height: 100%;
  gap: var(--space-lg);
}

.header-logo {
  color: var(--color-text-inverse);
  font-size: 1.25rem;
  font-weight: 700;
  white-space: nowrap;
  letter-spacing: -0.02em;
}

.header-logo span {
  color: var(--color-accent);
}

.header-search {
  flex: 1;
  max-width: 420px;
  position: relative;
}

.header-search input {
  width: 100%;
  padding: 8px 16px 8px 36px;
  border-radius: 20px;
  border: none;
  background: oklch(25% 0.04 265);
  color: var(--color-text-inverse);
  font-size: 0.875rem;
  outline: none;
  transition: background 0.2s;
}

.header-search input::placeholder { color: oklch(65% 0.02 265); }
.header-search input:focus { background: oklch(30% 0.05 265); }

.header-search .search-icon {
  position: absolute;
  left: 12px;
  top: 50%;
  transform: translateY(-50%);
  color: oklch(65% 0.02 265);
  font-size: 0.875rem;
}

.header-nav {
  display: flex;
  align-items: center;
  gap: var(--space-xl);
}

.header-nav a {
  color: oklch(85% 0.01 265);
  font-size: 0.9375rem;
  font-weight: 500;
  transition: color 0.2s;
  white-space: nowrap;
}

.header-nav a:hover { color: var(--color-accent); }

.hamburger {
  display: none;
  flex-direction: column;
  gap: 5px;
  padding: 4px;
  cursor: pointer;
}

.hamburger span {
  display: block;
  width: 22px;
  height: 2px;
  background: var(--color-text-inverse);
  border-radius: 2px;
  transition: transform 0.3s, opacity 0.3s;
}

.hamburger.active span:nth-child(1) { transform: translateY(7px) rotate(45deg); }
.hamburger.active span:nth-child(2) { opacity: 0; }
.hamburger.active span:nth-child(3) { transform: translateY(-7px) rotate(-45deg); }

.mobile-nav {
  display: none;
  background: var(--color-primary);
  border-top: 1px solid oklch(25% 0.04 265);
  padding: var(--space-md) var(--space-lg);
}

.mobile-nav.active { display: block; }

.mobile-nav a {
  display: block;
  color: oklch(85% 0.01 265);
  padding: var(--space-sm) 0;
  font-size: 1rem;
  font-weight: 500;
}

.mobile-nav a:hover { color: var(--color-accent); }

/* --- Hero Banner --- */
.hero-banner {
  background: oklch(25% 0.06 265);
  text-align: center;
  padding: var(--space-md) var(--space-lg);
}

.hero-banner p {
  color: oklch(90% 0.01 265);
  font-size: 1rem;
  font-weight: 500;
}

.hero-banner a {
  color: var(--color-accent);
  font-weight: 600;
}

.hero-banner a:hover { text-decoration: underline; }

/* --- Featured Article --- */
.featured-article {
  padding: var(--space-2xl) 0;
}

.featured-card {
  position: relative;
  border-radius: var(--radius-lg);
  overflow: hidden;
  background: var(--color-primary);
  min-height: 380px;
  display: flex;
  align-items: flex-end;
  transition: transform 0.2s;
}

.featured-card:hover { transform: translateY(-2px); }

.featured-card .featured-thumb {
  position: absolute;
  inset: 0;
  background: linear-gradient(135deg, oklch(30% 0.08 265), oklch(20% 0.06 200));
  z-index: 0;
}

.featured-card .featured-thumb::after {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(to top, oklch(10% 0.05 265 / 0.9) 0%, oklch(10% 0.05 265 / 0.3) 50%, transparent 100%);
}

.featured-content {
  position: relative;
  z-index: 1;
  padding: var(--space-xl);
  width: 100%;
}

.featured-tag {
  display: inline-block;
  background: var(--color-tag-ai);
  color: white;
  padding: 3px 10px;
  border-radius: var(--radius-sm);
  font-size: 0.75rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  margin-bottom: var(--space-sm);
}

.featured-title {
  color: var(--color-text-inverse);
  font-size: 1.75rem;
  font-weight: 700;
  line-height: 1.3;
  margin-bottom: var(--space-md);
  max-width: 600px;
}

.featured-meta {
  display: flex;
  align-items: center;
  gap: var(--space-sm);
  color: oklch(80% 0.01 265);
  font-size: 0.875rem;
}

.author-avatar {
  width: 28px;
  height: 28px;
  border-radius: 50%;
  background: oklch(60% 0.1 265);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 0.7rem;
  font-weight: 700;
  color: white;
  flex-shrink: 0;
}

/* --- Section Headers --- */
.section-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: var(--space-lg);
  padding-bottom: var(--space-sm);
  border-bottom: 2px solid var(--color-border);
}

.section-title {
  font-size: 1.375rem;
  font-weight: 700;
  color: var(--color-text);
}

.section-link {
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--color-link);
}

/* --- Article Grid --- */
.articles-section {
  padding: 0 0 var(--space-3xl);
}

.article-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--space-lg);
}

.article-card {
  background: var(--color-bg-card);
  border-radius: var(--radius-lg);
  overflow: hidden;
  box-shadow: var(--shadow-sm);
  border: 1px solid var(--color-border-light);
  transition: transform 0.2s, box-shadow 0.2s;
}

.article-card:hover {
  transform: translateY(-2px);
  box-shadow: var(--shadow-md);
}

.card-thumb {
  height: 160px;
  background: linear-gradient(135deg, oklch(70% 0.06 265), oklch(60% 0.04 200));
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
}

.card-thumb .card-icon {
  font-size: 2.5rem;
  opacity: 0.3;
}

.card-tag {
  position: absolute;
  top: var(--space-sm);
  left: var(--space-sm);
  padding: 2px 8px;
  border-radius: var(--radius-sm);
  font-size: 0.6875rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  color: white;
}

.tag-ai { background: var(--color-tag-ai); }
.tag-scraping { background: var(--color-tag-scraping); }
.tag-db { background: var(--color-tag-db); }
.tag-search { background: var(--color-tag-search); }
.tag-data { background: var(--color-tag-data); }
.tag-python { background: var(--color-tag-python); }
.tag-node { background: var(--color-tag-node); }
.tag-sheets { background: var(--color-tag-sheets); }
.tag-automation { background: var(--color-tag-automation); }

.card-body {
  padding: var(--space-md);
}

.card-title {
  font-size: 1rem;
  font-weight: 600;
  line-height: 1.4;
  margin-bottom: var(--space-sm);
  color: var(--color-text);
  display: -webkit-box;
  -webkit-line-clamp: 3;
  -webkit-box-orient: vertical;
  overflow: hidden;
}

.card-title a { color: inherit; }
.card-title a:hover { color: var(--color-link); }

.card-meta {
  display: flex;
  align-items: center;
  gap: var(--space-sm);
  font-size: 0.8125rem;
  color: var(--color-text-muted);
}

.card-meta .author-name { font-weight: 500; color: var(--color-text-secondary); }
.card-meta .separator { color: var(--color-border); }

/* --- Load More --- */
.load-more-wrapper {
  text-align: center;
  margin-top: var(--space-2xl);
}

.btn-load-more {
  background: var(--color-primary);
  color: var(--color-text-inverse);
  padding: 12px 32px;
  border-radius: var(--radius-md);
  font-size: 0.9375rem;
  font-weight: 600;
  transition: background 0.2s, transform 0.1s;
}

.btn-load-more:hover { background: var(--color-primary-light); }
.btn-load-more:active { transform: scale(0.98); }

/* --- Learn Page --- */
.page-intro {
  padding: var(--space-2xl) 0 var(--space-xl);
  text-align: center;
}

.page-intro h1 {
  font-size: 2rem;
  font-weight: 700;
  margin-bottom: var(--space-sm);
}

.page-intro p {
  color: var(--color-text-secondary);
  font-size: 1.0625rem;
  max-width: 520px;
  margin: 0 auto;
}

.curriculum-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
  gap: var(--space-md);
  padding-bottom: var(--space-2xl);
}

.cert-card {
  background: var(--color-bg-card);
  border: 1px solid var(--color-border-light);
  border-radius: var(--radius-lg);
  padding: var(--space-lg);
  display: flex;
  align-items: flex-start;
  gap: var(--space-md);
  transition: border-color 0.2s, box-shadow 0.2s;
  cursor: pointer;
}

.cert-card:hover {
  border-color: var(--color-accent);
  box-shadow: var(--shadow-md);
}

.cert-icon {
  width: 44px;
  height: 44px;
  border-radius: var(--radius-md);
  background: oklch(95% 0.02 85);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.25rem;
  flex-shrink: 0;
}

.cert-info h3 {
  font-size: 1rem;
  font-weight: 600;
  margin-bottom: 2px;
}

.cert-info p {
  font-size: 0.8125rem;
  color: var(--color-text-muted);
}

/* Daily Challenge */
.daily-challenge {
  background: oklch(97% 0.02 85);
  border-radius: var(--radius-lg);
  padding: var(--space-xl);
  text-align: center;
  margin-bottom: var(--space-2xl);
}

.daily-challenge h2 {
  font-size: 1.375rem;
  margin-bottom: var(--space-sm);
}

.daily-challenge p {
  color: var(--color-text-secondary);
  margin-bottom: var(--space-md);
}

.daily-challenge-links {
  display: flex;
  justify-content: center;
  gap: var(--space-lg);
  flex-wrap: wrap;
}

.daily-challenge-links a {
  font-weight: 600;
  font-size: 0.9375rem;
}

/* Language & Interview */
.sub-section {
  padding-bottom: var(--space-2xl);
}

.sub-section h2 {
  font-size: 1.375rem;
  font-weight: 700;
  margin-bottom: var(--space-md);
  padding-bottom: var(--space-sm);
  border-bottom: 2px solid var(--color-border);
}

.link-list {
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-sm);
}

.link-list a {
  background: var(--color-bg-card);
  border: 1px solid var(--color-border-light);
  padding: 8px 16px;
  border-radius: var(--radius-md);
  font-size: 0.9375rem;
  font-weight: 500;
  transition: border-color 0.2s, background 0.2s;
}

.link-list a:hover {
  border-color: var(--color-accent);
  background: oklch(98% 0.01 85);
}

/* --- Donate Page --- */
.donate-hero {
  background: var(--color-primary);
  padding: var(--space-3xl) 0;
  text-align: center;
}

.donate-hero h1 {
  color: var(--color-text-inverse);
  font-size: 2.25rem;
  font-weight: 700;
  margin-bottom: var(--space-md);
}

.donate-hero p {
  color: oklch(80% 0.01 265);
  font-size: 1.0625rem;
  max-width: 620px;
  margin: 0 auto;
  line-height: 1.7;
}

/* Donation Form */
.donate-form-section {
  padding: var(--space-2xl) 0;
}

.donate-form-card {
  max-width: 560px;
  margin: 0 auto;
  background: var(--color-bg-card);
  border-radius: var(--radius-xl);
  padding: var(--space-2xl);
  box-shadow: var(--shadow-lg);
}

.amount-tabs {
  display: flex;
  gap: var(--space-sm);
  margin-bottom: var(--space-lg);
}

.amount-tab {
  flex: 1;
  padding: 14px 8px;
  border-radius: var(--radius-md);
  font-size: 1.125rem;
  font-weight: 700;
  text-align: center;
  border: 2px solid var(--color-border);
  background: var(--color-bg-card);
  color: var(--color-text);
  transition: all 0.2s;
}

.amount-tab:hover { border-color: var(--color-accent); }

.amount-tab.active {
  background: var(--color-accent);
  border-color: var(--color-accent);
  color: var(--color-primary);
}

.donate-description {
  text-align: center;
  margin-bottom: var(--space-lg);
  font-size: 1rem;
  color: var(--color-text-secondary);
  line-height: 1.6;
}

.btn-donate {
  display: block;
  width: 100%;
  padding: 16px;
  background: var(--color-accent);
  color: var(--color-primary);
  border-radius: var(--radius-md);
  font-size: 1.125rem;
  font-weight: 700;
  text-align: center;
  transition: background 0.2s, transform 0.1s;
}

.btn-donate:hover { background: var(--color-accent-hover); }
.btn-donate:active { transform: scale(0.98); }

.donate-sublabel {
  text-align: center;
  margin-top: var(--space-sm);
  font-size: 0.8125rem;
  color: var(--color-text-muted);
}

/* Supporter Benefits */
.supporter-section {
  padding: var(--space-2xl) 0;
}

.benefits-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(260px, 1fr));
  gap: var(--space-md);
}

.benefit-item {
  display: flex;
  align-items: flex-start;
  gap: var(--space-md);
  padding: var(--space-md);
  background: var(--color-bg-card);
  border-radius: var(--radius-md);
  border: 1px solid var(--color-border-light);
}

.benefit-icon {
  width: 36px;
  height: 36px;
  border-radius: var(--radius-sm);
  background: oklch(95% 0.02 85);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1rem;
  flex-shrink: 0;
}

.benefit-item p {
  font-size: 0.9375rem;
  line-height: 1.5;
  color: var(--color-text-secondary);
}

/* Initiatives */
.initiatives-section {
  padding: var(--space-2xl) 0;
}

.initiative-list {
  display: grid;
  gap: var(--space-sm);
}

.initiative-item {
  display: flex;
  align-items: flex-start;
  gap: var(--space-md);
  padding: var(--space-md) var(--space-lg);
  background: var(--color-bg-elevated);
  border-radius: var(--radius-md);
}

.initiative-item .initiative-bullet {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--color-accent);
  margin-top: 7px;
  flex-shrink: 0;
}

.initiative-item p {
  font-size: 1rem;
  color: var(--color-text-secondary);
}

/* Achievements */
.achievements-section {
  padding: var(--space-2xl) 0;
}

.achievement-list {
  display: grid;
  gap: var(--space-sm);
}

.achievement-item {
  display: flex;
  align-items: flex-start;
  gap: var(--space-md);
  padding: var(--space-md) var(--space-lg);
  background: var(--color-bg-elevated);
  border-radius: var(--radius-md);
}

.achievement-item .achievement-bullet {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--color-link);
  margin-top: 7px;
  flex-shrink: 0;
}

.achievement-item p {
  font-size: 1rem;
  color: var(--color-text-secondary);
}

/* FAQ Accordion */
.faq-section {
  padding: var(--space-2xl) 0 var(--space-3xl);
}

.faq-list {
  max-width: 720px;
  margin: 0 auto;
}

.faq-item {
  border-bottom: 1px solid var(--color-border);
}

.faq-question {
  display: flex;
  align-items: center;
  justify-content: space-between;
  width: 100%;
  padding: var(--space-md) 0;
  font-size: 1rem;
  font-weight: 600;
  color: var(--color-text);
  text-align: left;
  transition: color 0.2s;
}

.faq-question:hover { color: var(--color-link); }

.faq-chevron {
  font-size: 0.75rem;
  transition: transform 0.3s;
  color: var(--color-text-muted);
  flex-shrink: 0;
  margin-left: var(--space-md);
}

.faq-item.active .faq-chevron { transform: rotate(180deg); }

.faq-answer {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.3s ease, padding 0.3s ease;
}

.faq-answer-inner {
  padding-bottom: var(--space-md);
  font-size: 0.9375rem;
  line-height: 1.7;
  color: var(--color-text-secondary);
}

.faq-item.active .faq-answer {
  max-height: 300px;
}

/* --- Tag Pages --- */
.tag-page-header {
  padding: var(--space-2xl) 0 var(--space-lg);
}

.tag-page-header h1 {
  font-size: 2rem;
  font-weight: 700;
}

.tag-page-header .tag-count {
  color: var(--color-text-muted);
  font-size: 1rem;
  margin-top: var(--space-xs);
}

.popular-tags-section {
  padding-bottom: var(--space-xl);
}

.popular-tags-row {
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-sm);
}

.popular-tag {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 6px 14px;
  background: var(--color-bg-card);
  border: 1px solid var(--color-border-light);
  border-radius: 20px;
  font-size: 0.8125rem;
  font-weight: 500;
  color: var(--color-text-secondary);
  transition: border-color 0.2s, background 0.2s;
  cursor: pointer;
}

.popular-tag:hover {
  border-color: var(--color-accent);
  background: oklch(98% 0.01 85);
}

.popular-tag .tag-count-badge {
  font-size: 0.75rem;
  color: var(--color-text-muted);
  font-weight: 400;
}

/* --- Footer --- */
.site-footer {
  background: var(--color-primary);
  color: oklch(80% 0.01 265);
  padding: var(--space-2xl) 0 var(--space-xl);
}

.footer-inner {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 var(--space-lg);
}

.footer-mission {
  font-size: 0.9375rem;
  line-height: 1.7;
  max-width: 700px;
  margin-bottom: var(--space-xl);
}

.footer-trending h4 {
  color: var(--color-accent);
  font-size: 0.875rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  margin-bottom: var(--space-sm);
}

.footer-trending p {
  font-size: 0.875rem;
  line-height: 1.8;
}

.footer-trending p span {
  color: oklch(85% 0.01 265);
  cursor: pointer;
  transition: color 0.2s;
}

.footer-trending p span:hover { color: var(--color-accent); }

.footer-links {
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-sm) var(--space-md);
  margin-top: var(--space-xl);
  padding-top: var(--space-lg);
  border-top: 1px solid oklch(25% 0.04 265);
}

.footer-links a {
  color: oklch(70% 0.01 265);
  font-size: 0.8125rem;
}

.footer-links a:hover { color: var(--color-accent); }

/* --- Responsive --- */
@media (max-width: 1024px) {
  .article-grid { grid-template-columns: repeat(2, 1fr); }
}

@media (max-width: 768px) {
  .header-search { display: none; }
  .header-nav { display: none; }
  .hamburger { display: flex; }

  .article-grid { grid-template-columns: 1fr; }
  .curriculum-grid { grid-template-columns: 1fr; }

  .featured-title { font-size: 1.375rem; }

  .donate-hero h1 { font-size: 1.75rem; }
  .donate-form-card { padding: var(--space-lg); }

  .amount-tabs { flex-wrap: wrap; }
  .amount-tab { min-width: calc(50% - 4px); }

  .benefits-grid { grid-template-columns: 1fr; }

  .tag-page-header h1 { font-size: 1.5rem; }
  .popular-tags-row { gap: 6px; }
}

@media (max-width: 480px) {
  .container { padding: 0 var(--space-md); }
  .header-inner { padding: 0 var(--space-md); }

  .hero-banner { padding: var(--space-sm) var(--space-md); }
  .hero-banner p { font-size: 0.875rem; }

  .featured-card { min-height: 280px; }
  .featured-content { padding: var(--space-md); }
  .featured-title { font-size: 1.25rem; }
}

/* --- Utility --- */
.visually-hidden {
  position: absolute;
  width: 1px;
  height: 1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
}

raw_arguments.content:
/* ===== OpenLearnHub Design System ===== */

/* --- OKLCH Color Tokens --- */
:root {
  --color-primary: oklch(15% 0.05 265);
  --color-primary-light: oklch(22% 0.06 265);
  --color-accent: oklch(80% 0.16 85);
  --color-accent-hover: oklch(75% 0.18 85);
  --color-link: oklch(40% 0.20 265);
  --color-link-hover: oklch(50% 0.22 265);

  --color-bg: oklch(99% 0.005 265);
  --color-bg-card: oklch(100% 0 0);
  --color-bg-elevated: oklch(97% 0.005 265);

  --color-text: oklch(20% 0.02 265);
  --color-text-secondary: oklch(45% 0.02 265);
  --color-text-muted: oklch(60% 0.015 265);
  --color-text-inverse: oklch(98% 0.005 265);

  --color-border: oklch(92% 0.01 265);
  --color-border-light: oklch(96% 0.005 265);

  --color-tag-ai: oklch(55% 0.18 265);
  --color-tag-scraping: oklch(60% 0.15 145);
  --color-tag-db: oklch(50% 0.17 300);
  --color-tag-search: oklch(60% 0.18 30);
  --color-tag-data: oklch(55% 0.16 200);
  --color-tag-python: oklch(60% 0.18 85);
  --color-tag-node: oklch(55% 0.18 145);
  --color-tag-sheets: oklch(60% 0.16 145);
  --color-tag-automation: oklch(50% 0.15 30);

  --radius-sm: 4px;
  --radius-md: 8px;
  --radius-lg: 12px;
  --radius-xl: 16px;

  --shadow-sm: 0 1px 3px oklch(0% 0 0 / 0.08);
  --shadow-md: 0 2px 8px oklch(0% 0 0 / 0.1);
  --shadow-lg: 0 4px 16px oklch(0% 0 0 / 0.12);

  --font-sans: 'Inter', system-ui, -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
  --font-mono: 'Fira Code', 'Cascadia Code', ui-monospace, monospace;

  --space-xs: 4px;
  --space-sm: 8px;
  --space-md: 16px;
  --space-lg: 24px;
  --space-xl: 32px;
  --space-2xl: 48px;
  --space-3xl: 64px;

  --max-width: 1200px;
  --header-height: 64px;
}

/* --- Reset & Base --- */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

html { font-size: 16px; -webkit-font-smoothing: antialiased; -moz-osx-font-smoothing: grayscale; }

body {
  font-family: var(--font-sans);
  color: var(--color-text);
  background: var(--color-bg);
  line-height: 1.6;
  min-height: 100vh;
}

a { color: var(--color-link); text-decoration: none; transition: color 0.2s; }
a:hover { color: var(--color-link-hover); }

img { max-width: 100%; display: block; }

ul, ol { list-style: none; }

button { cursor: pointer; font-family: inherit; border: none; background: none; }

/* --- Container --- */
.container {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 var(--space-lg);
}

/* --- Header --- */
.site-header {
  background: var(--color-primary);
  height: var(--header-height);
  position: sticky;
  top: 0;
  z-index: 100;
}

.header-inner {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 var(--space-lg);
  display: flex;
  align-items: center;
  height: 100%;
  gap: var(--space-lg);
}

.header-logo {
  color: var(--color-text-inverse);
  font-size: 1.25rem;
  font-weight: 700;
  white-space: nowrap;
  letter-spacing: -0.02em;
}

.header-logo span {
  color: var(--color-accent);
}

.header-search {
  flex: 1;
  max-width: 420px;
  position: relative;
}

.header-search input {
  width: 100%;
  padding: 8px 16px 8px 36px;
  border-radius: 20px;
  border: none;
  background: oklch(25% 0.04 265);
  color: var(--color-text-inverse);
  font-size: 0.875rem;
  outline: none;
  transition: background 0.2s;
}

.header-search input::placeholder { color: oklch(65% 0.02 265); }
.header-search input:focus { background: oklch(30% 0.05 265); }

.header-search .search-icon {
  position: absolute;
  left: 12px;
  top: 50%;
  transform: translateY(-50%);
  color: oklch(65% 0.02 265);
  font-size: 0.875rem;
}

.header-nav {
  display: flex;
  align-items: center;
  gap: var(--space-xl);
}

.header-nav a {
  color: oklch(85% 0.01 265);
  font-size: 0.9375rem;
  font-weight: 500;
  transition: color 0.2s;
  white-space: nowrap;
}

.header-nav a:hover { color: var(--color-accent); }

.hamburger {
  display: none;
  flex-direction: column;
  gap: 5px;
  padding: 4px;
  cursor: pointer;
}

.hamburger span {
  display: block;
  width: 22px;
  height: 2px;
  background: var(--color-text-inverse);
  border-radius: 2px;
  transition: transform 0.3s, opacity 0.3s;
}

.hamburger.active span:nth-child(1) { transform: translateY(7px) rotate(45deg); }
.hamburger.active span:nth-child(2) { opacity: 0; }
.hamburger.active span:nth-child(3) { transform: translateY(-7px) rotate(-45deg); }

.mobile-nav {
  display: none;
  background: var(--color-primary);
  border-top: 1px solid oklch(25% 0.04 265);
  padding: var(--space-md) var(--space-lg);
}

.mobile-nav.active { display: block; }

.mobile-nav a {
  display: block;
  color: oklch(85% 0.01 265);
  padding: var(--space-sm) 0;
  font-size: 1rem;
  font-weight: 500;
}

.mobile-nav a:hover { color: var(--color-accent); }

/* --- Hero Banner --- */
.hero-banner {
  background: oklch(25% 0.06 265);
  text-align: center;
  padding: var(--space-md) var(--space-lg);
}

.hero-banner p {
  color: oklch(90% 0.01 265);
  font-size: 1rem;
  font-weight: 500;
}

.hero-banner a {
  color: var(--color-accent);
  font-weight: 600;
}

.hero-banner a:hover { text-decoration: underline; }

/* --- Featured Article --- */
.featured-article {
  padding: var(--space-2xl) 0;
}

.featured-card {
  position: relative;
  border-radius: var(--radius-lg);
  overflow: hidden;
  background: var(--color-primary);
  min-height: 380px;
  display: flex;
  align-items: flex-end;
  transition: transform 0.2s;
}

.featured-card:hover { transform: translateY(-2px); }

.featured-card .featured-thumb {
  position: absolute;
  inset: 0;
  background: linear-gradient(135deg, oklch(30% 0.08 265), oklch(20% 0.06 200));
  z-index: 0;
}

.featured-card .featured-thumb::after {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(to top, oklch(10% 0.05 265 / 0.9) 0%, oklch(10% 0.05 265 / 0.3) 50%, transparent 100%);
}

.featured-content {
  position: relative;
  z-index: 1;
  padding: var(--space-xl);
  width: 100%;
}

.featured-tag {
  display: inline-block;
  background: var(--color-tag-ai);
  color: white;
  padding: 3px 10px;
  border-radius: var(--radius-sm);
  font-size: 0.75rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  margin-bottom: var(--space-sm);
}

.featured-title {
  color: var(--color-text-inverse);
  font-size: 1.75rem;
  font-weight: 700;
  line-height: 1.3;
  margin-bottom: var(--space-md);
  max-width: 600px;
}

.featured-meta {
  display: flex;
  align-items: center;
  gap: var(--space-sm);
  color: oklch(80% 0.01 265);
  font-size: 0.875rem;
}

.author-avatar {
  width: 28px;
  height: 28px;
  border-radius: 50%;
  background: oklch(60% 0.1 265);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 0.7rem;
  font-weight: 700;
  color: white;
  flex-shrink: 0;
}

/* --- Section Headers --- */
.section-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: var(--space-lg);
  padding-bottom: var(--space-sm);
  border-bottom: 2px solid var(--color-border);
}

.section-title {
  font-size: 1.375rem;
  font-weight: 700;
  color: var(--color-text);
}

.section-link {
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--color-link);
}

/* --- Article Grid --- */
.articles-section {
  padding: 0 0 var(--space-3xl);
}

.article-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--space-lg);
}

.article-card {
  background: var(--color-bg-card);
  border-radius: var(--radius-lg);
  overflow: hidden;
  box-shadow: var(--shadow-sm);
  border: 1px solid var(--color-border-light);
  transition: transform 0.2s, box-shadow 0.2s;
}

.article-card:hover {
  transform: translateY(-2px);
  box-shadow: var(--shadow-md);
}

.card-thumb {
  height: 160px;
  background: linear-gradient(135deg, oklch(70% 0.06 265), oklch(60% 0.04 200));
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
}

.card-thumb .card-icon {
  font-size: 2.5rem;
  opacity: 0.3;
}

.card-tag {
  position: absolute;
  top: var(--space-sm);
  left: var(--space-sm);
  padding: 2px 8px;
  border-radius: var(--radius-sm);
  font-size: 0.6875rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  color: white;
}

.tag-ai { background: var(--color-tag-ai); }
.tag-scraping { background: var(--color-tag-scraping); }
.tag-db { background: var(--color-tag-db); }
.tag-search { background: var(--color-tag-search); }
.tag-data { background: var(--color-tag-data); }
.tag-python { background: var(--color-tag-python); }
.tag-node { background: var(--color-tag-node); }
.tag-sheets { background: var(--color-tag-sheets); }
.tag-automation { background: var(--color-tag-automation); }

.card-body {
  padding: var(--space-md);
}

.card-title {
  font-size: 1rem;
  font-weight: 600;
  line-height: 1.4;
  margin-bottom: var(--space-sm);
  color: var(--color-text);
  display: -webkit-box;
  -webkit-line-clamp: 3;
  -webkit-box-orient: vertical;
  overflow: hidden;
}

.card-title a { color: inherit; }
.card-title a:hover { color: var(--color-link); }

.card-meta {
  display: flex;
  align-items: center;
  gap: var(--space-sm);
  font-size: 0.8125rem;
  color: var(--color-text-muted);
}

.card-meta .author-name { font-weight: 500; color: var(--color-text-secondary); }
.card-meta .separator { color: var(--color-border); }

/* --- Load More --- */
.load-more-wrapper {
  text-align: center;
  margin-top: var(--space-2xl);
}

.btn-load-more {
  background: var(--color-primary);
  color: var(--color-text-inverse);
  padding: 12px 32px;
  border-radius: var(--radius-md);
  font-size: 0.9375rem;
  font-weight: 600;
  transition: background 0.2s, transform 0.1s;
}

.btn-load-more:hover { background: var(--color-primary-light); }
.btn-load-more:active { transform: scale(0.98); }

/* --- Learn Page --- */
.page-intro {
  padding: var(--space-2xl) 0 var(--space-xl);
  text-align: center;
}

.page-intro h1 {
  font-size: 2rem;
  font-weight: 700;
  margin-bottom: var(--space-sm);
}

.page-intro p {
  color: var(--color-text-secondary);
  font-size: 1.0625rem;
  max-width: 520px;
  margin: 0 auto;
}

.curriculum-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
  gap: var(--space-md);
  padding-bottom: var(--space-2xl);
}

.cert-card {
  background: var(--color-bg-card);
  border: 1px solid var(--color-border-light);
  border-radius: var(--radius-lg);
  padding: var(--space-lg);
  display: flex;
  align-items: flex-start;
  gap: var(--space-md);
  transition: border-color 0.2s, box-shadow 0.2s;
  cursor: pointer;
}

.cert-card:hover {
  border-color: var(--color-accent);
  box-shadow: var(--shadow-md);
}

.cert-icon {
  width: 44px;
  height: 44px;
  border-radius: var(--radius-md);
  background: oklch(95% 0.02 85);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.25rem;
  flex-shrink: 0;
}

.cert-info h3 {
  font-size: 1rem;
  font-weight: 600;
  margin-bottom: 2px;
}

.cert-info p {
  font-size: 0.8125rem;
  color: var(--color-text-muted);
}

/* Daily Challenge */
.daily-challenge {
  background: oklch(97% 0.02 85);
  border-radius: var(--radius-lg);
  padding: var(--space-xl);
  text-align: center;
  margin-bottom: var(--space-2xl);
}

.daily-challenge h2 {
  font-size: 1.375rem;
  margin-bottom: var(--space-sm);
}

.daily-challenge p {
  color: var(--color-text-secondary);
  margin-bottom: var(--space-md);
}

.daily-challenge-links {
  display: flex;
  justify-content: center;
  gap: var(--space-lg);
  flex-wrap: wrap;
}

.daily-challenge-links a {
  font-weight: 600;
  font-size: 0.9375rem;
}

/* Language & Interview */
.sub-section {
  padding-bottom: var(--space-2xl);
}

.sub-section h2 {
  font-size: 1.375rem;
  font-weight: 700;
  margin-bottom: var(--space-md);
  padding-bottom: var(--space-sm);
  border-bottom: 2px solid var(--color-border);
}

.link-list {
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-sm);
}

.link-list a {
  background: var(--color-bg-card);
  border: 1px solid var(--color-border-light);
  padding: 8px 16px;
  border-radius: var(--radius-md);
  font-size: 0.9375rem;
  font-weight: 500;
  transition: border-color 0.2s, background 0.2s;
}

.link-list a:hover {
  border-color: var(--color-accent);
  background: oklch(98% 0.01 85);
}

/* --- Donate Page --- */
.donate-hero {
  background: var(--color-primary);
  padding: var(--space-3xl) 0;
  text-align: center;
}

.donate-hero h1 {
  color: var(--color-text-inverse);
  font-size: 2.25rem;
  font-weight: 700;
  margin-bottom: var(--space-md);
}

.donate-hero p {
  color: oklch(80% 0.01 265);
  font-size: 1.0625rem;
  max-width: 620px;
  margin: 0 auto;
  line-height: 1.7;
}

/* Donation Form */
.donate-form-section {
  padding: var(--space-2xl) 0;
}

.donate-form-card {
  max-width: 560px;
  margin: 0 auto;
  background: var(--color-bg-card);
  border-radius: var(--radius-xl);
  padding: var(--space-2xl);
  box-shadow: var(--shadow-lg);
}

.amount-tabs {
  display: flex;
  gap: var(--space-sm);
  margin-bottom: var(--space-lg);
}

.amount-tab {
  flex: 1;
  padding: 14px 8px;
  border-radius: var(--radius-md);
  font-size: 1.125rem;
  font-weight: 700;
  text-align: center;
  border: 2px solid var(--color-border);
  background: var(--color-bg-card);
  color: var(--color-text);
  transition: all 0.2s;
}

.amount-tab:hover { border-color: var(--color-accent); }

.amount-tab.active {
  background: var(--color-accent);
  border-color: var(--color-accent);
  color: var(--color-primary);
}

.donate-description {
  text-align: center;
  margin-bottom: var(--space-lg);
  font-size: 1rem;
  color: var(--color-text-secondary);
  line-height: 1.6;
}

.btn-donate {
  display: block;
  width: 100%;
  padding: 16px;
  background: var(--color-accent);
  color: var(--color-primary);
  border-radius: var(--radius-md);
  font-size: 1.125rem;
  font-weight: 700;
  text-align: center;
  transition: background 0.2s, transform 0.1s;
}

.btn-donate:hover { background: var(--color-accent-hover); }
.btn-donate:active { transform: scale(0.98); }

.donate-sublabel {
  text-align: center;
  margin-top: var(--space-sm);
  font-size: 0.8125rem;
  color: var(--color-text-muted);
}

/* Supporter Benefits */
.supporter-section {
  padding: var(--space-2xl) 0;
}

.benefits-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(260px, 1fr));
  gap: var(--space-md);
}

.benefit-item {
  display: flex;
  align-items: flex-start;
  gap: var(--space-md);
  padding: var(--space-md);
  background: var(--color-bg-card);
  border-radius: var(--radius-md);
  border: 1px solid var(--color-border-light);
}

.benefit-icon {
  width: 36px;
  height: 36px;
  border-radius: var(--radius-sm);
  background: oklch(95% 0.02 85);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1rem;
  flex-shrink: 0;
}

.benefit-item p {
  font-size: 0.9375rem;
  line-height: 1.5;
  color: var(--color-text-secondary);
}

/* Initiatives */
.initiatives-section {
  padding: var(--space-2xl) 0;
}

.initiative-list {
  display: grid;
  gap: var(--space-sm);
}

.initiative-item {
  display: flex;
  align-items: flex-start;
  gap: var(--space-md);
  padding: var(--space-md) var(--space-lg);
  background: var(--color-bg-elevated);
  border-radius: var(--radius-md);
}

.initiative-item .initiative-bullet {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--color-accent);
  margin-top: 7px;
  flex-shrink: 0;
}

.initiative-item p {
  font-size: 1rem;
  color: var(--color-text-secondary);
}

/* Achievements */
.achievements-section {
  padding: var(--space-2xl) 0;
}

.achievement-list {
  display: grid;
  gap: var(--space-sm);
}

.achievement-item {
  display: flex;
  align-items: flex-start;
  gap: var(--space-md);
  padding: var(--space-md) var(--space-lg);
  background: var(--color-bg-elevated);
  border-radius: var(--radius-md);
}

.achievement-item .achievement-bullet {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--color-link);
  margin-top: 7px;
  flex-shrink: 0;
}

.achievement-item p {
  font-size: 1rem;
  color: var(--color-text-secondary);
}

/* FAQ Accordion */
.faq-section {
  padding: var(--space-2xl) 0 var(--space-3xl);
}

.faq-list {
  max-width: 720px;
  margin: 0 auto;
}

.faq-item {
  border-bottom: 1px solid var(--color-border);
}

.faq-question {
  display: flex;
  align-items: center;
  justify-content: space-between;
  width: 100%;
  padding: var(--space-md) 0;
  font-size: 1rem;
  font-weight: 600;
  color: var(--color-text);
  text-align: left;
  transition: color 0.2s;
}

.faq-question:hover { color: var(--color-link); }

.faq-chevron {
  font-size: 0.75rem;
  transition: transform 0.3s;
  color: var(--color-text-muted);
  flex-shrink: 0;
  margin-left: var(--space-md);
}

.faq-item.active .faq-chevron { transform: rotate(180deg); }

.faq-answer {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.3s ease, padding 0.3s ease;
}

.faq-answer-inner {
  padding-bottom: var(--space-md);
  font-size: 0.9375rem;
  line-height: 1.7;
  color: var(--color-text-secondary);
}

.faq-item.active .faq-answer {
  max-height: 300px;
}

/* --- Tag Pages --- */
.tag-page-header {
  padding: var(--space-2xl) 0 var(--space-lg);
}

.tag-page-header h1 {
  font-size: 2rem;
  font-weight: 700;
}

.tag-page-header .tag-count {
  color: var(--color-text-muted);
  font-size: 1rem;
  margin-top: var(--space-xs);
}

.popular-tags-section {
  padding-bottom: var(--space-xl);
}

.popular-tags-row {
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-sm);
}

.popular-tag {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 6px 14px;
  background: var(--color-bg-card);
  border: 1px solid var(--color-border-light);
  border-radius: 20px;
  font-size: 0.8125rem;
  font-weight: 500;
  color: var(--color-text-secondary);
  transition: border-color 0.2s, background 0.2s;
  cursor: pointer;
}

.popular-tag:hover {
  border-color: var(--color-accent);
  background: oklch(98% 0.01 85);
}

.popular-tag .tag-count-badge {
  font-size: 0.75rem;
  color: var(--color-text-muted);
  font-weight: 400;
}

/* --- Footer --- */
.site-footer {
  background: var(--color-primary);
  color: oklch(80% 0.01 265);
  padding: var(--space-2xl) 0 var(--space-xl);
}

.footer-inner {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 var(--space-lg);
}

.footer-mission {
  font-size: 0.9375rem;
  line-height: 1.7;
  max-width: 700px;
  margin-bottom: var(--space-xl);
}

.footer-trending h4 {
  color: var(--color-accent);
  font-size: 0.875rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  margin-bottom: var(--space-sm);
}

.footer-trending p {
  font-size: 0.875rem;
  line-height: 1.8;
}

.footer-trending p span {
  color: oklch(85% 0.01 265);
  cursor: pointer;
  transition: color 0.2s;
}

.footer-trending p span:hover { color: var(--color-accent); }

.footer-links {
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-sm) var(--space-md);
  margin-top: var(--space-xl);
  padding-top: var(--space-lg);
  border-top: 1px solid oklch(25% 0.04 265);
}

.footer-links a {
  color: oklch(70% 0.01 265);
  font-size: 0.8125rem;
}

.footer-links a:hover { color: var(--color-accent); }

/* --- Responsive --- */
@media (max-width: 1024px) {
  .article-grid { grid-template-columns: repeat(2, 1fr); }
}

@media (max-width: 768px) {
  .header-search { display: none; }
  .header-nav { display: none; }
  .hamburger { display: flex; }

  .article-grid { grid-template-columns: 1fr; }
  .curriculum-grid { grid-template-columns: 1fr; }

  .featured-title { font-size: 1.375rem; }

  .donate-hero h1 { font-size: 1.75rem; }
  .donate-form-card { padding: var(--space-lg); }

  .amount-tabs { flex-wrap: wrap; }
  .amount-tab { min-width: calc(50% - 4px); }

  .benefits-grid { grid-template-columns: 1fr; }

  .tag-page-header h1 { font-size: 1.5rem; }
  .popular-tags-row { gap: 6px; }
}

@media (max-width: 480px) {
  .container { padding: 0 var(--space-md); }
  .header-inner { padding: 0 var(--space-md); }

  .hero-banner { padding: var(--space-sm) var(--space-md); }
  .hero-banner p { font-size: 0.875rem; }

  .featured-card { min-height: 280px; }
  .featured-content { padding: var(--space-md); }
  .featured-title { font-size: 1.25rem; }
}

/* --- Utility --- */
.visually-hidden {
  position: absolute;
  width: 1px;
  height: 1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
}
